use crate::account::Kind;
use crate::position::{AccountPosition, Position};

/// What overall utilisation would become if this line were CLOSED.
///
/// The reason it matters is the reason "I'll close it" is dangerous advice: THEY MIGHT SAY YES. The
/// balance moves nowhere and the limit disappears, so utilisation across everything left jumps.
pub fn utilisation_if_closed(position: &Position, account: &str) -> Option<f64> {
    let lines: Vec<&AccountPosition> = position.accounts.iter().filter(|a| a.kind == Kind::Credit && a.credit_limit.is_some()).collect();
    let limit: i64 = lines.iter().filter(|a| a.account != account).map(|a| a.credit_limit.map(|l| l.minor).unwrap_or(0)).sum();
    if limit <= 0 {
        return None;
    }
    // The owed total keeps the CLOSED line's balance — that is the entire point. It does not go
    // anywhere; only the limit does.
    let owed: i64 = lines.iter().map(|a| a.owed.map(|o| o.minor).unwrap_or(0)).sum();
    Some((owed as f64 / limit as f64 * 1000.0).round() / 1000.0)
}
